def closest_pair_sum(nums, target):
    if len(nums) < 2:
        return None
    lo, hi = 0, len(nums) - 1
    best = nums[lo] + nums[hi]
    while lo < hi:
        s = nums[lo] + nums[hi]
        gap, best_gap = abs(s - target), abs(best - target)
        if gap < best_gap or (gap == best_gap and s < best):
            best = s
        if s < target:
            lo += 1
        elif s > target:
            hi -= 1
        else:
            return s
    return best

def count_pairs_below(nums, limit):
    vals = sorted(nums)
    lo, hi = 0, len(vals) - 1
    count = 0
    while lo < hi:
        if vals[lo] + vals[hi] < limit:
            count += hi - lo
            lo += 1
        else:
            hi -= 1
    return count

def distinct_squares(nums):
    lo, hi = 0, len(nums) - 1
    result = []
    while lo <= hi:
        left, right = nums[lo] * nums[lo], nums[hi] * nums[hi]
        if left > right:
            square = left
            lo += 1
        else:
            square = right
            hi -= 1
        if not result or result[-1] != square:
            result.append(square)
    result.reverse()
    return result

def almost_palindrome(s):
    def is_palindrome(lo, hi):
        while lo < hi:
            if s[lo] != s[hi]:
                return False
            lo += 1
            hi -= 1
        return True

    lo, hi = 0, len(s) - 1
    while lo < hi:
        if s[lo] != s[hi]:
            return is_palindrome(lo + 1, hi) or is_palindrome(lo, hi - 1)
        lo += 1
        hi -= 1
    return True

def compact_sorted(nums, k):
    write = 0
    for read in range(len(nums)):
        x = nums[read]
        if write < k or nums[write - k] != x:
            nums[write] = x
            write += 1
    return write

def triplets_with_sum(nums, target):
    vals = sorted(nums)
    n = len(vals)
    result = []
    for i in range(n - 2):
        if i > 0 and vals[i] == vals[i - 1]:
            continue
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = vals[i] + vals[lo] + vals[hi]
            if s < target:
                lo += 1
            elif s > target:
                hi -= 1
            else:
                result.append((vals[i], vals[lo], vals[hi]))
                lo += 1
                while lo < hi and vals[lo] == vals[lo - 1]:
                    lo += 1
                hi -= 1
    return result

def three_way_partition(nums, pivot):
    lt, i, gt = 0, 0, len(nums)
    while i < gt:
        if nums[i] < pivot:
            nums[lt], nums[i] = nums[i], nums[lt]
            lt += 1
            i += 1
        elif nums[i] > pivot:
            gt -= 1
            nums[i], nums[gt] = nums[gt], nums[i]
        else:
            i += 1
    return lt, gt

def trapped_water(heights):
    lo, hi = 0, len(heights) - 1
    left_max = right_max = water = 0
    while lo < hi:
        if heights[lo] < heights[hi]:
            left_max = max(left_max, heights[lo])
            water += left_max - heights[lo]
            lo += 1
        else:
            right_max = max(right_max, heights[hi])
            water += right_max - heights[hi]
            hi -= 1
    return water

def min_gap_between(a, b):
    if not a or not b:
        return None
    i = j = 0
    best = abs(a[0] - b[0])
    while i < len(a) and j < len(b):
        best = min(best, abs(a[i] - b[j]))
        if a[i] < b[j]:
            i += 1
        else:
            j += 1
    return best

def same_after_backspaces(s, t):
    def prev_char(text, i):
        skip = 0
        while i >= 0:
            if text[i] == "#":
                skip += 1
            elif skip:
                skip -= 1
            else:
                return i
            i -= 1
        return -1

    i, j = len(s) - 1, len(t) - 1
    while True:
        i, j = prev_char(s, i), prev_char(t, j)
        if i < 0 or j < 0:
            return i < 0 and j < 0
        if s[i] != t[j]:
            return False
        i -= 1
        j -= 1

def has_pair_with_difference(nums, k):
    i, j = 0, 1
    while j < len(nums):
        diff = nums[j] - nums[i]
        if i != j and diff == k:
            return True
        if i == j or diff < k:
            j += 1
        else:
            i += 1
    return False

def longest_unique_substring(s):
    last_seen = {}
    start = best_start = best_len = 0
    for i, ch in enumerate(s):
        if last_seen.get(ch, -1) >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        if i - start + 1 > best_len:
            best_start, best_len = start, i - start + 1
    return s[best_start:best_start + best_len]

def shortest_subarray_at_least(nums, target):
    best = len(nums) + 1
    window = left = 0
    for right, x in enumerate(nums):
        window += x
        while window >= target:
            best = min(best, right - left + 1)
            window -= nums[left]
            left += 1
    return best if best <= len(nums) else 0

from collections import defaultdict


def longest_k_distinct(s, k):
    counts = defaultdict(int)
    left = best = 0
    for right, ch in enumerate(s):
        counts[ch] += 1
        while len(counts) > k:
            counts[s[left]] -= 1
            if counts[s[left]] == 0:
                del counts[s[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

from collections import Counter


def min_window_cover(s, t):
    if not t:
        return ""
    need = Counter(t)
    missing = len(t)
    left = 0
    best_len, best_start = len(s) + 1, 0
    for right, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        while missing == 0:
            if right - left + 1 < best_len:
                best_len, best_start = right - left + 1, left
            need[s[left]] += 1
            if need[s[left]] > 0:
                missing += 1
            left += 1
    return s[best_start:best_start + best_len] if best_len <= len(s) else ""

def longest_ones_with_flips(bits, k):
    left = zeros = best = 0
    for right, b in enumerate(bits):
        if b == 0:
            zeros += 1
        while zeros > k:
            if bits[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

def count_small_product_subarrays(nums, k):
    if k <= 1:
        return 0
    product = 1
    left = count = 0
    for right, x in enumerate(nums):
        product *= x
        while product >= k:
            product //= nums[left]
            left += 1
        count += right - left + 1
    return count

def min_swaps_to_group_ones(bits):
    total = sum(bits)
    if total == 0:
        return 0
    ones = sum(bits[:total])
    best = ones
    for i in range(total, len(bits)):
        ones += bits[i] - bits[i - total]
        best = max(best, ones)
    return total - best

from collections import defaultdict


def count_exactly_k_distinct(nums, k):
    def at_most(m):
        if m <= 0:
            return 0
        counts = defaultdict(int)
        left = total = 0
        for right, x in enumerate(nums):
            counts[x] += 1
            while len(counts) > m:
                counts[nums[left]] -= 1
                if counts[nums[left]] == 0:
                    del counts[nums[left]]
                left += 1
            total += right - left + 1
        return total

    return at_most(k) - at_most(k - 1)

def count_in_ranges(s, queries):
    prefix = {}
    for letter in set(s):
        counts = [0]
        for c in s:
            counts.append(counts[-1] + (c == letter))
        prefix[letter] = counts
    answers = []
    for lo, hi, ch in queries:
        counts = prefix.get(ch)
        answers.append(counts[hi + 1] - counts[lo] if counts else 0)
    return answers

def balance_index(nums):
    total = sum(nums)
    left = 0
    for i, x in enumerate(nums):
        if left == total - left - x:
            return i
        left += x
    return -1

def region_sums(grid, queries):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    pre = [[0] * (cols + 1) for _ in range(rows + 1)]
    for r in range(rows):
        for c in range(cols):
            pre[r + 1][c + 1] = grid[r][c] + pre[r][c + 1] + pre[r + 1][c] - pre[r][c]
    return [
        pre[r2 + 1][c2 + 1] - pre[r1][c2 + 1] - pre[r2 + 1][c1] + pre[r1][c1]
        for r1, c1, r2, c2 in queries
    ]

def longest_equal_zeros_ones(bits):
    first = {0: -1}
    balance = best = 0
    for i, b in enumerate(bits):
        balance += 1 if b == 1 else -1
        if balance in first:
            best = max(best, i - first[balance])
        else:
            first[balance] = i
    return best

def can_carry_all(trips, capacity):
    if not trips:
        return True
    last = max(end for _, _, end in trips)
    change = [0] * (last + 1)
    for riders, start, end in trips:
        change[start] += riders
        change[end] -= riders
    load = 0
    for delta in change:
        load += delta
        if load > capacity:
            return False
    return True

def first_bracket_error(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for i, ch in enumerate(s):
        if ch in "([{":
            stack.append(i)
        elif ch in pairs:
            if not stack or s[stack[-1]] != pairs[ch]:
                return i
            stack.pop()
    return stack[0] if stack else -1

def eval_rpn(expr):
    stack = []
    for tok in expr.split():
        if tok not in ("+", "-", "*", "/"):
            stack.append(int(tok))
            continue
        b = stack.pop()
        a = stack.pop()
        if tok == "+":
            stack.append(a + b)
        elif tok == "-":
            stack.append(a - b)
        elif tok == "*":
            stack.append(a * b)
        else:
            q = abs(a) // abs(b)
            stack.append(q if (a >= 0) == (b > 0) else -q)
    return stack[0]

def next_greater_circular(nums):
    n = len(nums)
    result = [None] * n
    stack = []
    for i in range(2 * n):
        x = nums[i % n]
        while stack and nums[stack[-1]] < x:
            result[stack.pop()] = x
        if i < n:
            stack.append(i)
    return result

def simplify_path(path):
    stack = []
    for part in path.split("/"):
        if part == "..":
            if stack:
                stack.pop()
        elif part and part != ".":
            stack.append(part)
    return "/" + "/".join(stack)

def largest_rectangle(heights):
    stack = []  # (start index, height), heights increasing
    best = 0
    for i, h in enumerate(heights + [0]):
        start = i
        while stack and stack[-1][1] >= h:
            start, height = stack.pop()
            best = max(best, height * (i - start))
        stack.append((start, h))
    return best

def expand_repeats(s):
    stack = []  # (text before the bracket, its repeat count)
    current = ""
    count = 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == "[":
            stack.append((current, count))
            current, count = "", 0
        elif ch == "]":
            prefix, k = stack.pop()
            current = prefix + current * k
        else:
            current += ch
    return current

def smallest_after_removing(num, k):
    stack = []
    for d in num:
        while k and stack and stack[-1] > d:
            stack.pop()
            k -= 1
        stack.append(d)
    if k:
        stack = stack[:-k]
    return "".join(stack).lstrip("0") or "0"

def collapse_runs(s, k):
    stack = []  # [character, length of its current run]
    for ch in s:
        if stack and stack[-1][0] == ch:
            stack[-1][1] += 1
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([ch, 1])
    return "".join(ch * count for ch, count in stack)

import re


def tags_balanced(html):
    stack = []
    for closing, name in re.findall(r"<(/?)([A-Za-z]+)>", html):
        if not closing:
            stack.append(name)
        elif not stack or stack.pop() != name:
            return False
    return not stack

def longest_valid_parens(s):
    stack = [-1]  # bottom: index just before the current valid stretch
    best = 0
    for i, ch in enumerate(s):
        if ch == "(":
            stack.append(i)
        else:
            stack.pop()
            if stack:
                best = max(best, i - stack[-1])
            else:
                stack.append(i)
    return best

def stack_sequence_possible(pushed, popped):
    stack = []
    j = 0
    for x in pushed:
        stack.append(x)
        while stack and stack[-1] == popped[j]:
            stack.pop()
            j += 1
    return j == len(popped)
